describe('Element Manager - Add and Delete Elements', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  it('should add two elements and display two delete buttons, then delete one to leave one button', () => {
    // Verify initial state
    cy.get('[data-testid="element-list"]').should('be.visible');
    cy.get('[data-testid="add-element-btn"]').should('be.visible');
    cy.get('[data-testid="element-list"]').should('contain', '1 element');

    // Click 'Add Element' button twice
    cy.get('[data-testid="add-element-btn"]').click();
    cy.get('[data-testid="element-list"]').should('contain', '2 elements');
    cy.get('[data-testid="add-element-btn"]').click();
    cy.get('[data-testid="element-list"]').should('contain', '3 elements');

    // Verify two delete buttons are visible
    cy.get('[data-testid="delete-btn-1"]').should('be.visible');
    cy.get('[data-testid="delete-btn-2"]').should('be.visible');

    // Click first delete button
    cy.get('[data-testid="delete-btn-1"]').click();

    // Verify only one delete button remains
    cy.get('[data-testid="delete-btn-1"]').should('be.visible');
    cy.get('[data-testid="delete-btn-2"]').should('not.exist');

    // Verify list reflects one remaining element
    cy.get('[data-testid="element-list"]').should('contain', '1 element');
  });

  it('should handle edge case where no elements are initially present', () => {
    // Verify initial state with no elements
    cy.get('[data-testid="element-list"]').should('be.visible');
    cy.get('[data-testid="element-list"]').should('contain', '0 elements');

    // Click 'Add Element' button
    cy.get('[data-testid="add-element-btn"]').click();
    cy.get('[data-testid="element-list"]').should('contain', '1 element');

    // Verify delete button appears
    cy.get('[data-testid="delete-btn-1"]').should('be.visible');

    // Click delete button
    cy.get('[data-testid="delete-btn-1"]').click();

    // Verify list reflects one less element
    cy.get('[data-testid="element-list"]').should('contain', '0 elements');
  });
});
